				  const blurb = chinese ? skill.descriptionZh : skill.description
				  const used = typeof counts?.[skill.name] === 'number' ? counts[skill.name] : 0
				  const zh = typeof skill.displayNameZh === 'string' ? skill.displayNameZh : ''
